def minStickers(stickers, target):
    from functools import lru_cache
    letters = sorted(set(target))
    pos = {c: i for i, c in enumerate(letters)}
    need0 = [0] * len(letters)
    for c in target:
        need0[pos[c]] += 1
    vecs = []
    for st in stickers.split(","):
        v = [0] * len(letters)
        for c in st:
            if c in pos:
                v[pos[c]] += 1
        if any(v):
            vecs.append(v)
    by_letter = [[v for v in vecs if v[i]] for i in range(len(letters))]
    INF = float("inf")

    @lru_cache(maxsize=None)
    def f(need):
        first = -1
        for i, x in enumerate(need):
            if x:
                first = i
                break
        if first < 0:
            return 0
        best = INF
        for v in by_letter[first]:
            nxt = tuple(x - y if x > y else 0 for x, y in zip(need, v))
            r = f(nxt)
            if r + 1 < best:
                best = r + 1
        return best

    ans = f(tuple(need0))
    return -1 if ans == INF else ans
